const input = $json;

const severity = input.severity === 'critical' ? '🚨' : '⚠️';

let detailsText;
if (input.details === null || input.details === undefined) {
  detailsText = 'Sin contenido adicional';
} else if (typeof input.details === 'object') {
  detailsText = JSON.stringify(input.details, null, 2);
} else {
  detailsText = String(input.details);
}
const safeDetails = detailsText.replace(/`/g, "'").slice(0, 2800);

// Dominio base desde variable de entorno o fallback
const baseUrl = (typeof $env !== 'undefined' && $env.WEBHOOK_URL)
  ? $env.WEBHOOK_URL.replace(/\/$/, '')
  : 'http://localhost:5678';

// Construcción limpia de la URL hacia la ejecución
const executionUrl = `${baseUrl}/workflow/${input.sourceWorkflowId}/executions/${input.sourceExecutionId}`;

const blocks = [
  { 
    type: 'header', 
    text: { type: 'plain_text', text: `${severity}${input.title}`, emoji: true } 
  },
  { 
    type: 'section', 
    text: { type: 'mrkdwn', text: `*Detalle:*\n\`\`\`${safeDetails}\`\`\`` } 
  },
  { 
    type: 'context', 
    elements: [
      { type: 'mrkdwn', text: `<${executionUrl}|🔍 Ver ejecución completa en n8n>` }
    ] 
  }
];

return [{ json: { blocks } }];
